package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.apache.commons.lang3.builder.EqualsBuilder;
import org.apache.commons.lang3.builder.ToStringBuilder;
import org.apache.commons.lang3.builder.ToStringStyle;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ArrayUtils_lastIndexOf_TriageGen1Test {

    private static final int INDEX_NOT_FOUND = -1;







    @Test
    public void testLastIndexOf_StartIndexOutOfBoundsLarge() {
        boolean[] array = {true, false, true};
        // startIndex >= array.length, should clamp to array.length - 1 (index 2)
        // array[2] is true, so it should find it at index 2
        assertEquals(2, ArrayUtils.lastIndexOf(array, true, 5));
        // array[2] is true, looking for false, should go backwards and find index 1
        assertEquals(1, ArrayUtils.lastIndexOf(array, false, 5));
    }










}

